// Codegen tests: the committed generated files are exactly the deterministic
// generator output and expose the whole contract model.

import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import test from "node:test";

import {
  CONTRACT_VERSION,
  GENERATED_DIR,
  GENERATED_FILES,
  PACKAGE_DIR,
  generate,
} from "../codegen.mjs";
import { OPERATION_TYPES } from "../index.mjs";

const read = (file) => readFileSync(join(GENERATED_DIR, file), "utf8");
const firstLine = (content) => content.split("\n", 1)[0];

test("the generated directory holds exactly the two committed files", () => {
  assert.deepEqual(readdirSync(GENERATED_DIR).sort(), [...GENERATED_FILES].sort());
});

test("the committed generated files equal the generator output", () => {
  const output = generate();
  for (const file of GENERATED_FILES) {
    assert.equal(read(file), output.get(file), `${file} is up to date`);
  }
});

test("codegen is deterministic and free of timestamps and absolute paths", () => {
  const first = generate();
  const second = generate();
  for (const file of GENERATED_FILES) {
    const content = first.get(file);
    assert.equal(second.get(file), content, `${file} is stable`);
    assert.ok(content.startsWith(`// Generated by codegen.mjs from packages/contracts/schemas. Do not edit by hand.\n`));
    assert.ok(content.includes(CONTRACT_VERSION));
    assert.ok(!/\b(19|20)\d{2}-\d{2}-\d{2}\b/.test(content), `${file} carries no date`);
    assert.ok(!content.includes(PACKAGE_DIR), `${file} carries no absolute package path`);
    assert.ok(!content.includes("/Users/"), `${file} carries no absolute user path`);
    assert.ok(content.endsWith("\n"), `${file} ends with a newline`);
  }
});

test("the TypeScript output exposes the entities, enums, union and inverse pair", () => {
  const types = read("types.ts");
  assert.equal(firstLine(types), "// Generated by codegen.mjs from packages/contracts/schemas. Do not edit by hand.");
  for (const name of ["Account", "Workspace", "Board", "Note", "Card", "Zone", "Block", "Edge", "BoardContent", "CardEndpoint"]) {
    assert.ok(types.includes(`export interface ${name} {`), `interface ${name}`);
  }
  for (const name of ["AccountLocale", "BlockType", "BoardVisibility", "DeleteZonePolicy", "OperationType"]) {
    assert.ok(types.includes(`export type ${name} = `), `enum ${name}`);
  }
  assert.ok(types.includes("export type Operation = {"));
  assert.ok(types.includes("inverse: OperationInverse;"));
  assert.ok(types.includes("export type OperationInverse = {"));
  assert.ok(types.includes("export type OperationPayload = "));
  assert.ok(types.includes("export type OperationInversePayload = "));
  assert.ok(types.includes("export interface GroupPayload {"));
  assert.ok(types.includes("export interface GroupInversePayload {"));
  assert.ok(types.includes("children: Operation[];"));
  assert.ok(types.includes("children: OperationInverse[];"));
  for (const type of OPERATION_TYPES) {
    assert.ok(types.includes(`type: "${type}"`), `operation ${type} in the union`);
  }
  assert.equal(types.includes("[object Object]"), false);
});

test("the generated files carry the 0.4.0 reorder payload in both languages", () => {
  const types = read("types.ts");
  const header = read("contract.h");
  assert.ok(types.includes("export interface ReorderPayload {"));
  assert.ok(types.includes("  itemId: string;"));
  assert.ok(types.includes("  z: string;"));
  assert.ok(types.includes('| { payload: ReorderPayload; type: "reorder" }'));
  assert.ok(header.includes("struct ReorderPayload {"));
  assert.ok(header.includes("std::string itemId;"));
  assert.ok(header.includes("std::string z;"));
  assert.ok(/using OperationPayload = std::variant<[^>]*ReorderPayload/.test(header));
  assert.ok(/using OperationInversePayload = std::variant<[^>]*ReorderPayload/.test(header));
});

test("the generated operation vocabulary matches the contract index", () => {
  const types = read("types.ts");
  const line = types.split("\n").find((entry) => entry.startsWith("export const OPERATION_TYPES = "));
  assert.ok(line !== undefined);
  const values = [...line.matchAll(/"([^"]+)"/g)].map((match) => match[1]).sort();
  assert.deepEqual(values, [...OPERATION_TYPES].sort());
});

test("the C++ output exposes the model, enums and the operation envelope", () => {
  const header = read("contract.h");
  assert.equal(firstLine(header), "// Generated by codegen.mjs from packages/contracts/schemas. Do not edit by hand.");
  assert.ok(header.includes("#pragma once"));
  assert.ok(header.includes("namespace project_air::contracts {"));
  assert.ok(header.includes('inline constexpr const char* kContractVersion = "0.4.0";'));
  for (const name of ["Account", "Workspace", "Board", "Note", "Card", "Zone", "Block", "Edge", "BoardContent", "CardEndpoint"]) {
    assert.ok(header.includes(`struct ${name} {`), `struct ${name}`);
  }
  for (const name of ["AccountLocale", "BlockType", "BoardVisibility", "DeleteZonePolicy", "OperationType"]) {
    assert.ok(header.includes(`enum class ${name} {`), `enum class ${name}`);
  }
  assert.ok(header.includes("struct OperationInverse {"));
  assert.ok(header.includes("struct Operation {"));
  assert.ok(header.includes("using OperationPayload = std::variant<"));
  assert.ok(header.includes("using OperationInversePayload = std::variant<"));
  assert.ok(header.includes("std::vector<Operation> children;"));
  assert.ok(header.includes("std::vector<OperationInverse> children;"));
  assert.ok(header.includes("std::optional<std::string> zoneId;"));
  assert.ok(header.includes("#include <variant>"));
});
